package com.geometrybox.game;
import android.app.Activity;import android.os.Bundle;import android.view.*;import android.graphics.*;import android.content.pm.ActivityInfo;import android.view.WindowManager;import android.os.SystemClock;import java.util.Random;
public class MainActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);getWindow().setFlags(1024,1024);setContentView(new Game());}
 class Game extends View{Paint p=new Paint(3);float y=0,vy=0,obs=850,speed=9,ground;int score=0;boolean started=false,dead=false;long last;Random r=new Random();Game(){super(MainActivity.this);}void label(Canvas c,String s,float x,float yy,int size){p.setColor(Color.WHITE);p.setTextSize(size);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText(s,x,yy,p);}
 protected void onDraw(Canvas c){int w=getWidth(),h=getHeight();ground=h*.78f;c.drawColor(Color.rgb(9,12,35));p.setColor(Color.rgb(0,220,255));p.setStrokeWidth(4);c.drawLine(0,ground,w,ground,p);if(started&&!dead){long now=SystemClock.uptimeMillis();if(last!=0){float dt=Math.min(.04f,(now-last)/1000f);vy+=1800*dt;y+=vy*dt;obs-=speed*dt*60;if(y>0){y=0;vy=0;}if(obs< -50){obs=w+250+r.nextInt(250);score++;speed=Math.min(15,speed+.2f);}}last=now;}float cy=ground-42+y;p.setColor(Color.CYAN);c.drawRoundRect(90,cy,132,cy+42,6,6,p);p.setColor(Color.rgb(255,55,130));Path t=new Path();t.moveTo(obs,ground);t.lineTo(obs+25,ground-45);t.lineTo(obs+50,ground);t.close();c.drawPath(t,p);if(started&&!dead&&obs<145&&obs+50>90&&cy+42>ground-43)dead=true;label(c,"GEOMETRY BOX",25,40,24);label(c,"SCORE: "+score,w-150,40,22);if(!started)label(c,"TAP TO START",w/2f-100,h/2f,28);if(dead){label(c,"GAME OVER",w/2f-90,h/2f,30);label(c,"TAP TO RESTART",w/2f-115,h/2f+40,20);}postInvalidateDelayed(16);}
 public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){if(dead){dead=false;started=true;score=0;speed=9;obs=getWidth()+200;y=0;vy=0;last=0;}else{started=true;if(y==0)vy=-650;}invalidate();return true;}return true;}}
}
